struct LongVec {
    long items[16];
    unsigned int count;
    void push_back(long v) { items[count++] = v; }
    void erase(unsigned int pos)
    {
        long* position = items + pos;
        long* finish = items + count;
        if (position + 1 != finish)
            std::memmove(position, position + 1, (const char*)finish - (const char*)(position + 1));
        --count;
    }
};

